INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27901, '2 Corinthians 12:12', '2 Corinthians', 12, 12, '&nbsp;د رښتينى رسول نښې ستاسو په وړاندې ما په ډېر صبر سره په نښو او په معجزو او عجيبه کارونو ښکاره کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27902, '2 Corinthians 12:13', '2 Corinthians', 12, 13, '&nbsp;تاسو په کومه خبره کښې د نورو جماعتونو نه کم وئ بې له دې چې ما په خپله په تاسو بوج وانۀ چولو؟ زما دا غلطى معاف کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27903, '2 Corinthians 12:14', '2 Corinthians', 12, 14, '&nbsp;ګورئ، په درېم ځل زۀ تاسو له راتلو ته تيار يم او په تاسو به بوج وانۀ چوم، ځکه چې زۀ ستاسو د مال نه بلکې ستاسو غوښتونکے يم. ځکه چې ماشومان مور پلار نۀ ساتى بلکې مور پلار ماشومان ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27904, '2 Corinthians 12:15', '2 Corinthians', 12, 15, '&nbsp;زۀ به ستاسو دپاره ډېر څۀ په خوشحالۍ قربان کړم بلکې تر دې چې خپل ځان به هم قربان کړم. کۀ زۀ تاسو سره زياته مينه کوم نو ولې تاسو به ما سره کمه مينه کوئ څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27905, '2 Corinthians 12:16', '2 Corinthians', 12, 16, '&nbsp;دا خبره ټيک ده چې ما په تاسو بوج وانۀ چولو، خو ځينى دا سوچ کوى چې زۀ چالاک يم او تاسو مې په ټګۍ راګېر کړى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27906, '2 Corinthians 12:17', '2 Corinthians', 12, 17, '&nbsp;نو بيا څوک چې ما تاسو ته درولېږل نو ولې ما د هغوئ په وسيله تاسو سره څۀ دوکه کړې ده څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27907, '2 Corinthians 12:18', '2 Corinthians', 12, 18, '&nbsp;ما تيطوس ته مِنت وکړو چې هغه لاړ شى او هغۀ سره مې يو ورور درولېږلو، خو تيطوس ولې تاسو سره دوکه ونۀ کړه څۀ؟ ولې مونږ دواړه په يو روح کښې نۀ يُو؟ ولې مونږ د يو بل په نقش قدم نۀ يُو روان څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27908, '2 Corinthians 12:19', '2 Corinthians', 12, 19, '&nbsp;کېدے چې تاسو دا سوچ کوئ چې مونږ ستاسو په وړاندې د خپل ځان دفاع کوُو؟ خو مونږ د خُدائ پاک په وړاندې په مسيح کښې خبرې کوُو. خوږو عزيزانو، دا هر څۀ مونږ ستاسو د ترقۍ دپاره کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27909, '2 Corinthians 12:20', '2 Corinthians', 12, 20, '&nbsp;ځکه چې زۀ يرېږم، هسې نه چې کله زۀ درشم او تاسو چې څنګه غواړم هغه شان مو ونۀ مومم، او څنګه چې تاسو نۀ غواړئ ما هغه شان ومومئ، زۀ يرېږم چې په تاسو کښې جګړه، کينه، غصه، خود غرضى، بده وينا، غېبتونه، ډوزې او فساد نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27910, '2 Corinthians 12:21', '2 Corinthians', 12, 21, '&nbsp;په دې يرېږم چې کله زۀ بيا درشم هسې نه چې زما خُدائ پاک ما ستاسو په وړاندې شرمنده نۀ کړى او په هغه ډېرو خلقو چې ګناهونه يې کړى دى، افسوس وکړم ځکه چې هغوئ د هغې ناپاکۍ، حرامکارۍ او شهوت پرستۍ نه چې يې کړى دى، توبه نۀ ده ايستلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27911, '2 Corinthians 13:1', '2 Corinthians', 13, 1, '&nbsp;دا درېم ځل دے چې زۀ تاسو ته درځم، د دې دپاره چې د هر اِلزام دپاره د دوو يا درېو ګواهانو ضرورت به وى چې هغه پرې مجرم ثابت کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27912, '2 Corinthians 13:2', '2 Corinthians', 13, 2, '&nbsp;ما هغوئ او هغه نور ټول خبردار کړل چا چې مخکښې ګناه کړې وه، او زۀ هغوئ اوس هم هغه شان په غېر موجودګۍ کښې خبرداروم څنګه چې ما په دوېم ځل کړى وُو، چې زۀ بيا راشم نو ضرور به سزا ورکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27913, '2 Corinthians 13:3', '2 Corinthians', 13, 3, '&nbsp;ځکه چې تاسو کوم ثبوت غواړئ چې مسيح زما په وسيله خبرې کوى هغه زۀ اوس تاسو له درکوم. هغه ستاسو د سمولو دپاره کمزورے نۀ دے بلکې هغه په تاسو کښې طاقتور دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27914, '2 Corinthians 13:4', '2 Corinthians', 13, 4, '&nbsp;ځکه چې هغه په کمزورتيا کښې په سولۍ کړے شو خو د خُدائ پاک د قدرت په سبب ژوندے دے. او مونږ هم په هغۀ کښې کمزورى يُو خو د هغۀ سره به د خُدائ پاک د هغه قدرت په سبب ژوندى يُو چې ستاسو اصلاح وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27915, '2 Corinthians 13:5', '2 Corinthians', 13, 5, '&nbsp;تاسو خپل ځانونه وآزمايئ چې ستاسو ايمان په ځائ دے او کۀ نه. خپل ځانونه ولټوئ. ولې تاسو په دې نۀ يئ خبر چې عيسىٰ مسيح په تاسو کښې اوسيږى؟ کۀ په تاسو کښې هغه نۀ وى، نو بيا ستاسو ايمان بې‌ځايه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27916, '2 Corinthians 13:6', '2 Corinthians', 13, 6, '&nbsp;زۀ اُميد کوم چې تاسو ته به پته ولګى چې مونږ ناکامه نۀ يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27917, '2 Corinthians 13:7', '2 Corinthians', 13, 7, '&nbsp;خو مونږ د خُدائ پاک نه دا دُعا غواړو چې تاسو څۀ بد کار ونۀ کړئ، د دې دپاره نه چې مونږ کامياب ښکاره شُو بلکې د دې دپاره چې تاسو نېکى وکړئ، خير دے کۀ مونږ ناکاميابه ښکاره شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27918, '2 Corinthians 13:8', '2 Corinthians', 13, 8, '&nbsp;ځکه چې مونږ د حق خِلاف هيڅ نۀ شُو کولے خو د حق آواز اوچتولے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27919, '2 Corinthians 13:9', '2 Corinthians', 13, 9, '&nbsp;نو ځکه مونږ خوشحاله يُو کله چې مونږ کمزورى يُو او تاسو زورَور يئ. او زمونږ دا دُعا ده چې تاسو په ايمان کښې پاخۀ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27920, '2 Corinthians 13:10', '2 Corinthians', 13, 10, '&nbsp;نو زۀ دا خبرې په خپلې غېر موجودګۍ کښې د دې دپاره ليکم نو کله چې زۀ درشم چې زۀ د هغه اختيار په استعمالولو کښې سختى ونۀ کړم کوم اختيار چې مالِک ما له ستاسو د جوړولو دپاره راکړے دے، او نۀ چې د ورانولو دپاره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27921, '2 Corinthians 13:11', '2 Corinthians', 13, 11, '&nbsp;اے وروڼو او خوېندو زما آخرى خبره دا ده چې، خوشحاله اوسئ، په هر څۀ کښې بالغان شئ، يو بل ته ډاډګيرنه ورکوئ، په امن سره اوسېږئ، نو بيا به د مينې او د سلامتۍ خُدائ پاک تاسو سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27922, '2 Corinthians 13:12', '2 Corinthians', 13, 12, '&nbsp;په پاکې مينې سره يو بل ته سلام ووايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27923, '2 Corinthians 13:13', '2 Corinthians', 13, 13, '&nbsp;ټول مقدسين تاسو ته سلام وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27924, '2 Corinthians 13:14', '2 Corinthians', 13, 14, '&nbsp;د مالِک عيسىٰ مسيح فضل او د خُدائ پاک مينه او د روحُ القُدس شراکت دې تاسو ټولو سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27925, 'Galatians 1:1', 'Galatians', 1, 1, '&nbsp;د پولوس رسول د طرف نه، چې نۀ هغه انسانانو مقرر کړو، او نۀ يې د بل چا نه رسالت حاصل کړو، بلکې عيسىٰ مسيح او خُدائ پلار په خپله مقرر کړو، چا چې مسيح د مړو نه بيا ژوندے کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27926, 'Galatians 1:2', 'Galatians', 1, 2, '&nbsp;زۀ او ما سره موجود ايمانداران وروڼه د ګلتيانو ټولو جماعتونو ته سلام وايو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27927, 'Galatians 1:3', 'Galatians', 1, 3, '&nbsp;زمونږ د خُدائ پلار او د مالِک عيسىٰ مسيح د طرفه دې په تاسو فضل او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27928, 'Galatians 1:4', 'Galatians', 1, 4, '&nbsp;هغه عيسىٰ چا چې زمونږ د ګناهونو دپاره خپل ځان قربان کړو، د دې دپاره چې زمونږ د خُدائ پلار د رضا په مطابق د دې موجوده بدکارې زمانې نه مونږ بچ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27929, 'Galatians 1:5', 'Galatians', 1, 5, '&nbsp;د خُدائ پاک جلال دې د تل دپاره وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27930, 'Galatians 1:6', 'Galatians', 1, 6, '&nbsp;زۀ په دې خبره حېران يم چې تاسو دومره زر د هغه چا نه مخ اړوئ چا چې تاسو د مسيح په فضل رابللى يئ، او اوس د بل زېرى پسې ګرځئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27931, 'Galatians 1:7', 'Galatians', 1, 7, '&nbsp;اګر چې بل زيرے نشته. خو داسې خلق شته چې هغوئ دا غواړى چې تاسو بې‌لارې کړى او د مسيح د زيرى مقصد درته بدل کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27932, 'Galatians 1:8', 'Galatians', 1, 8, '&nbsp;خو کۀ مونږ په خپله يا د آسمان يوه فرښته د هغه زېرى نه علاوه چې مونږ تاسو ته اورولے وو، بل کوم زيرے اوروى، نو هغه دې لعنتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27933, 'Galatians 1:9', 'Galatians', 1, 9, '&nbsp;زۀ اوس هغه څۀ تاسو ته بيا بيانوم څۀ چې ما درته اول بيان کړى دى، کۀ چرې څوک تاسو ته د در رسېدلى زېرى نه بل زيرے اوروى نو هغه دې لعنتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27934, 'Galatians 1:10', 'Galatians', 1, 10, '&nbsp;ولې زۀ اوس د بنى آدم د راضى کولو کوشش کوم يا د خُدائ پاک؟ يا ولې زۀ د خلقو د خوشحالولو پسې ګرځم؟ کۀ چرې ما تر اوسه پورې خلق خوشحالول نو بيا به زۀ د مسيح غلام نۀ وم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27935, 'Galatians 1:11', 'Galatians', 1, 11, '&nbsp;زما وروڼو او خوېندو، زۀ دا غواړم چې تاسو په دې پوهه شئ چې کوم زيرے چې ما درته اورَولے دے هغه انسانى نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27936, 'Galatians 1:12', 'Galatians', 1, 12, '&nbsp;ځکه چې هغه ما ته د چا انسان په وسيله نۀ دے رارسېدلے او نۀ چا ما ته ښودلے دے، بلکې دا ما ته د عيسىٰ مسيح د خوا نه اظهار شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27937, 'Galatians 1:13', 'Galatians', 1, 13, '&nbsp;نو بې‌شکه تاسو زما د مخکښې ژوند په حقله کله چې يهودى وم دا اورېدلى دى چې ما به د خُدائ پاک جماعت زورولو او د هغې د تباه کولو کوشش کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27938, 'Galatians 1:14', 'Galatians', 1, 14, '&nbsp;زۀ د يهوديانو په عقيده کښې د خپل قوم د اکثرو همزولو نه ډېر سرګرم وم ځکه چې زۀ د خپلو مشرانو د رواياتو ډېر زيات پابند وم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27939, 'Galatians 1:15', 'Galatians', 1, 15, '&nbsp;خو خُدائ پاک زۀ د پېدايښت نه مخکښې د مور په ګېډه کښې خوښ کړم او په خپل فضل يې راوبللم، نو هغه خوشحاله وو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27940, 'Galatians 1:16', 'Galatians', 1, 16, '&nbsp;چې خپل زوئ په ما کښې څرګند کړى د دې دپاره چې زۀ په غېر‌يهوديانو کښې د هغۀ زيرے خور کړم. نو نۀ خو ما د انسان نه صلاح واخسته', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27941, 'Galatians 1:17', 'Galatians', 1, 17, '&nbsp;او نۀ زۀ په يروشلم کښې هغوئ ته ورغلم څوک چې زما نه مخکښې رسولان وُو، بلکې سمدستى عربستان ته لاړم او د هغه ځائ نه وروستو دمشق ته راواپس شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27942, 'Galatians 1:18', 'Galatians', 1, 18, '&nbsp;بيا درې کاله پس د پطروس سره د ملاقات دپاره زۀ يروشلم ته لاړم او پينځلس ورځې مې هغۀ سره تېرې کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27943, 'Galatians 1:19', 'Galatians', 1, 19, '&nbsp;خو ما د مالِک د ورور يعقوب نه بغېر نورو رسولانو سره ملاقات ونۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27944, 'Galatians 1:20', 'Galatians', 1, 20, '&nbsp;کومې خبرې چې زۀ تاسو ته ليکم، خُدائ پاک حاضر ناظر دے چې زۀ هيڅ دروغ نۀ وايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27945, 'Galatians 1:21', 'Galatians', 1, 21, '&nbsp;د دې نه پس زۀ د شام او د کلکيه علاقو ته لاړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27946, 'Galatians 1:22', 'Galatians', 1, 22, '&nbsp;او په يهوديه کښې چې د مسيح جماعتونه دى هغوئ زۀ تر اوسه نۀ پېژندلم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
