(27954, 'Galatians 2:6', 'Galatians', 2, 6, '&nbsp;او کوم خلق چې مشران حسابېدل، هغه کۀ هر څنګه وُو، زما ورسره هيڅ کار نشته ځکه چې خُدائ پاک د هيچا طرفدارے نۀ کوى، د هغه مشرانو نه زما په زېرى کښې هيڅ زياتوالے رانۀ غلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27955, 'Galatians 2:7', 'Galatians', 2, 7, '&nbsp;خو د دې قاعدې په خلاف، هغوئ وليدل چې ما ته د غېر‌يهوديانو دپاره د مسيح د زيرى ذمه وارى حواله شوې ده، لکه څنګه چې پطروس ته د يهوديانو دپاره د زيرى ذمه وارى حواله شوې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27956, 'Galatians 2:8', 'Galatians', 2, 8, '&nbsp;نو دغه شان، څنګه چې خُدائ پاک په پطروس کښې د يهوديانو د رسالت دپاره طاقت پېدا کړو، نو هم هغۀ د غېرو يهوديانو د رسالت دپاره ما ته هم طاقت راکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27957, 'Galatians 2:9', 'Galatians', 2, 9, '&nbsp;او کله چې يعقوب، پطروس او يوحنا چې د جماعت ستنې وې، هغوئ د هغه فضل نه خبر شول کوم چې ما ته راکړے شوے وو، نو هغوئ د ملګرتيا دپاره برنباس او ما ته ښے لاس راکړو. او مونږ متفِق شو چې مونږ به غېر‌يهوديانو ته او هغوئ به يهوديانو ته د خِدمت دپاره لاړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27958, 'Galatians 2:10', 'Galatians', 2, 10, '&nbsp;هغوئ بس دومره راته ووئيل چې خوار غريب ياد ساته، ولې زۀ پخپله د دې کار دپاره ليواله وم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27959, 'Galatians 2:11', 'Galatians', 2, 11, '&nbsp;خو کله چې پطروس اَنطاکيه ته راغلو نو ما مخامخ د هغۀ مخالفت وکړو ځکه چې هغه په خپله ملامته وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27960, 'Galatians 2:12', 'Galatians', 2, 12, '&nbsp;کله چې هغه راغلو نو هغۀ د غېر‌يهوديانو ايماندارانو سره خوړل څښل، خو وروستو کله چې د يعقوب ملګرى راغلۀ نو هغۀ نور د غېر‌يهوديانو سره خوړل څښل پرېښودل. ځکه چې هغه د هغه خلقو نه يرېدو چا چې د غېر‌يهوديانو سنتېدل غوښتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27961, 'Galatians 2:13', 'Galatians', 2, 13, '&nbsp;او نور يهوديان وروڼه هم د هغۀ په مرسته په رياکارۍ کښې ورسره شامل شول تر دې چې برنباس هم د هغوئ سره د رياکارۍ په وجه ګمراه شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27962, 'Galatians 2:14', 'Galatians', 2, 14, '&nbsp;نو کله چې ما وليدل چې هغوئ د زيرى د رښتينوالى په مطابق په نېغه لار نۀ ځى، نو ما د ټولو په وړاندې پطروس ته دا ووئيل چې، ”کۀ څۀ هم چې تۀ يهودى يې او د غېر‌يهوديانو په شان ژوند تېروې، نو بيا تۀ ولې غېرقومونه د يهوديانو په شان ژوند تېرولو ته مجبوروې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
