(27982, 'Galatians 3:13', 'Galatians', 3, 13, '&nbsp;مسيح مونږ په بيعه واخستو او د شريعت د لعنت نه يې آزاد کړُو ځکه چې هغه زمونږ دپاره لعنتى شو، ځکه چې په صحيفو کښې ليکلے شوى دى چې، ”څوک چې په ونه کښې راځوړند کړے شى هغه لعنتى دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27983, 'Galatians 3:14', 'Galatians', 3, 14, '&nbsp;دا ځکه وشو چې د اِبراهيم برکت د عيسىٰ مسيح په وسيله غېر‌يهوديانو ته هم ور ورسى، او چې مونږ د ايمان په وسيله د روحُ القُدس هغه وعده حاصله کړُو د کوم چې خُدائ پاک وعده کړې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27984, 'Galatians 3:15', 'Galatians', 3, 15, '&nbsp;زما وروڼو او خوېندو، زۀ درته د روزمره ژوند مثال درکوم. چې د يو کس د چا سره تړون وشى، نو بيا په کښې نۀ څۀ زياتېدے شى او نۀ څۀ منسوخ کېدے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27985, 'Galatians 3:16', 'Galatians', 3, 16, '&nbsp;نو خُدائ پاک چې د اِبراهيم او د هغۀ د اولاد سره کومه وعده وکړه، نو د هغۀ مقصد دا نۀ وو چې، ”د ډېرو اولادونو سره،“ بلکې د هغۀ مقصد دا وو چې، ”ستا يک يو اولاد سره،“ يعنې مسيح سره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27986, 'Galatians 3:17', 'Galatians', 3, 17, '&nbsp;زما مقصد دا دے، کوم شريعت چې څلور سوه دېرش کاله وروستو راغلو، دا هغه تړون نۀ ماتوى کوم چې خُدائ پاک د پخوا نه مقرر کړے وو او نۀ د هغۀ وعده ماتوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27987, 'Galatians 3:18', 'Galatians', 3, 18, '&nbsp;ځکه کۀ ميراث د شريعت په وسيله حاصليږى نو بيا خو به دا د وعدې په بنياد نۀ دے، خو خُدائ پاک اِبراهيم ته دا د وعدې په وسيله ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27988, 'Galatians 3:19', 'Galatians', 3, 19, '&nbsp;نو بيا د شريعت د راتلو نه څۀ مقصد وو؟ شريعت د دې دپاره ورکړے شو چې د وعدې سره سره چې خلقو ته د هغوئ ګناهونه هم ورښکاره کړى، خو شريعت صرف د وعده شوى ماشوم د راتلو پورې وو. خُدائ پاک خپل شريعت د فرښتو په وسيله موسىٰ له ورکړو څوک چې د خُدائ پاک او خلقو تر مينځه مينځګړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27989, 'Galatians 3:20', 'Galatians', 3, 20, '&nbsp;خو د مينځګړى ضرورت په هغه وخت راځى کله چې فريقېن د يو نه زيات شى، خو خُدائ پاک يو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27990, 'Galatians 3:21', 'Galatians', 3, 21, '&nbsp;نو ولې شريعت د خُدائ پاک د وعدو خلاف دے؟ نه، هيڅکله نه. ځکه چې کۀ داسې شريعت ورکړے شوے وے چې ژوند يې ورکولو نو بيا به صداقت د شريعت په وسيله راغلے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27991, 'Galatians 3:22', 'Galatians', 3, 22, '&nbsp;خو صحيفې فرمائى چې مونږ ټول د ګناه بنديوان يُو، نو کومه د معافۍ وعده چې د عيسىٰ مسيح په ايمان کښې ده، هغه به هغه خلقو له ورکړے شى د چا چې پرې ايمان وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27992, 'Galatians 3:23', 'Galatians', 3, 23, '&nbsp;نو د ايمان د راتلو نه اول، مونږ په قېد کښې وُو او د شريعت د لاندې تر هغې څارل کېدو ترڅو چې په مونږ کښې ايمان څرګند شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27993, 'Galatians 3:24', 'Galatians', 3, 24, '&nbsp;په دې وجه شريعت د مسيح د راتلو پورې زمونږ څارونکے وو د دې دپاره چې مونږ د ايمان په وسيله صادق ثابت کړے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27994, 'Galatians 3:25', 'Galatians', 3, 25, '&nbsp;خو اوس چې ايمان راغلو نو مونږ نور د شريعت څارلو ته محتاج نۀ يُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27995, 'Galatians 3:26', 'Galatians', 3, 26, '&nbsp;ځکه چې په عيسىٰ مسيح کښې د ايمان په وسيله تاسو ټول د خُدائ پاک اولاد يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27996, 'Galatians 3:27', 'Galatians', 3, 27, '&nbsp;تاسو څومره چې په مسيح کښې بپتسمه شوى يئ، د مسيح جامې مو اغوستې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27997, 'Galatians 3:28', 'Galatians', 3, 28, '&nbsp;په تاسو کښې نور نۀ څوک اوس يهودى او نۀ يونانى، نۀ څوک غلام او نۀ آزاد، نۀ څوک نارينه او نۀ زنانه شته، ځکه چې تاسو ټول اوس په عيسىٰ مسيح کښې يو شان يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27998, 'Galatians 3:29', 'Galatians', 3, 29, '&nbsp;او اوس چې تاسو د مسيح يئ نو تاسو د اِبراهيم اولاد يئ، او د وعدې په مطابق وارثان يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27999, 'Galatians 4:1', 'Galatians', 4, 1, '&nbsp;خو زۀ دا وايم ترڅو چې وارث نابالغه وى، اګر چې هغه د ټول جائېداد مالِک وى، خو ترڅو چې هغه بالغ شوے نۀ وى تر هغې پورې په هغۀ او يو غلام کښې فرق نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28000, 'Galatians 4:2', 'Galatians', 4, 2, '&nbsp;پلار چې کوم وخت د هغوئ دپاره مقرر کړے دے نو تر هغه وخته پورې به هغوئ د هغه ساتونکى تابعدارى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');